<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/functions.php';require_permission($pdo,'view_clients');$active='clients';$pageTitle='Clients';
$rows=$pdo->query("SELECT c.*,u.name,u.email,u.status user_status,(SELECT COUNT(*) FROM orders o WHERE o.client_id=c.id) orders_count FROM clients c JOIN users u ON u.id=c.user_id ORDER BY c.id DESC")->fetchAll();include __DIR__.'/../../includes/header.php';?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><span class="eyebrow">PEOPLE</span><h1 class="page-title">Clients</h1></div><?php if(has_permission($pdo,'manage_clients')):?><a href="form.php" class="btn btn-stare">Add Client</a><?php endif;?></div>
<div class="panel"><div class="table-responsive"><table class="table stare-table align-middle"><thead><tr><th>Client</th><th>Phone</th><th>Address</th><th>Orders</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><div class="text-secondary small"><?=e($r['email'])?></div></td><td><?=e($r['phone'])?></td><td><?=e($r['address'])?></td><td><?=$r['orders_count']?></td><td><?=status_badge($r['status'])?></td><td><?php if(has_permission($pdo,'manage_clients')):?><a href="form.php?id=<?=$r['id']?>" class="action-link">Edit</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
